//! Cross-check: `websearch::pdftext` reproduces the Python
//! `websearch.pdftext` byte-for-byte on minimal PDF blobs — a
//! FlateDecode-compressed content stream (literal + `TJ` array + hex
//! string), an uncompressed stream, `/Title` (literal, octal-escaped,
//! and unsupported hex forms), literal escapes/octal, `max_chars`
//! truncation, and empty/garbage input.
//!
//! @generated by tests/regen_pdftext_goldens.py — DO NOT EDIT BY HAND.
//! Regenerate:
//!   PYTHONPATH=legacy-python/websearch python3 \
//!     crates/websearch/tests/regen_pdftext_goldens.py \
//!     > crates/websearch/tests/xcheck_pdftext.rs
//!
//! Inputs and the UTF-8 of each expected (latin-1) output are hex so
//! both sides see identical bytes; compressed streams are embedded from
//! `zlib.compress`, so Python and Rust inflate the very same input.

struct Fx {
    name: &'static str,
    max_chars: usize,
    input: &'static str,
    text: &'static str,
    title: &'static str,
}

fn unhex(s: &str) -> Vec<u8> {
    let b = s.as_bytes();
    let mut out = Vec::with_capacity(b.len() / 2);
    let mut i = 0;
    while i + 1 < b.len() {
        let hi = (b[i] as char).to_digit(16).unwrap();
        let lo = (b[i + 1] as char).to_digit(16).unwrap();
        out.push((hi * 16 + lo) as u8);
        i += 2;
    }
    out
}

