#[test]
fn pdftext_matches_python() {
    for fx in FIXTURES {
        let input = unhex(fx.input);
        let want_text = String::from_utf8(unhex(fx.text)).unwrap();
        let got_text = websearch::pdftext::extract_text(&input, fx.max_chars);
        assert_eq!(got_text, want_text, "extract_text mismatch: {}", fx.name);
        let want_title = String::from_utf8(unhex(fx.title)).unwrap();
        let got_title = websearch::pdftext::extract_title(&input);
        assert_eq!(got_title, want_title, "extract_title mismatch: {}", fx.name);
    }
}
